SELECT , u.nickname, u.avatar, (SELECT COUNT(scl.id) > 0 FROM sys_comment_like scl WHERE scl.comment_id = c.id AND scl.user_id = #{userId,jdbcType=BIGINT}) AS is_like FROM sys_comment c LEFT JOIN sys_user u ON c.user_id = u.id WHERE c.is_deleted = 0 AND c.parent_id IS NULL AND c.business_id = #{businessId} AND c.comment_type = #{commentType}
ORDER BY c.is_stick DESC, c.like_count DESC, c.id DESC
ORDER BY c.is_stick DESC, c.create_time DESC, c.id DESC

WITH RECURSIVE descendants AS (
    SELECT c.id FROM sys_comment c WHERE c.parent_id = #{id}
    UNION ALL
    SELECT c.id FROM sys_comment c JOIN descendants d ON c.parent_id = d.id
)
SELECT id FROM descendants WHERE id  <>  #{id}
